package com.portfolio.orderservice.api; import com.portfolio.orderservice.domain.CustomerOrder; import com.portfolio.orderservice.repo.CustomerOrderRepository; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*; @RestController @RequestMapping("/api/v1/orders") public class CustomerOrderController { private final CustomerOrderRepository repo; public CustomerOrderController(CustomerOrderRepository r){repo=r;} @GetMapping Page<CustomerOrder> list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return repo.findAll(PageRequest.of(page,Math.min(100,size)));} @GetMapping("/{id}") CustomerOrder get(@PathVariable long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));} @PostMapping ResponseEntity<CustomerOrder> create(@Valid @RequestBody CustomerOrderRequest r){ CustomerOrder e=new CustomerOrder();e.setProductId(r.productId());e.setQuantity(r.quantity());e.setCustomerEmail(r.customerEmail());return ResponseEntity.status(201).body(repo.save(e));} }